// ===== the old model, kept and made strict: left = where you are, bottom = what you can do, right = the window =====
const CW = 296;
const leftCard = (title, kind, facts, sections, o) => { o = o || {}; return card({ left: '12px', top: '12px', width: CW + 'px' }, '<div style="padding: 14px 14px 12px;">' +
  (o.crumb ? '<div style="' + st({ display: 'flex', alignItems: 'center', gap: '4px', fontSize: '12px', color: K.muted, marginBottom: '6px' }) + '">' + o.crumb + '</div>' : '') +
  '<div style="' + st({ display: 'flex', alignItems: 'center', gap: '8px' }) + '">' + (o.back ? sq(I.back) : '') + '<span style="' + st({ flex: 1, display: 'flex', flexDirection: 'column', gap: '1px', minWidth: 0 }) + '">' + t(title, { fontSize: '17px', lineHeight: '22px', fontWeight: 600, letterSpacing: '-.01em' }) + (kind ? mu(kind, { fontSize: '12.5px' }) : '') + '</span>' + (o.x ? '<span style="display: inline-flex; color: ' + K.muted + ';">' + ic(I.x, 17) + '</span>' : '') + '</div>' +
  (facts ? '<div style="' + st({ marginTop: '8px', fontSize: '13px', lineHeight: '19px', color: K.ink }) + '">' + facts + '</div>' : '') + '</div>' +
  (sections || []).map((s) => '<div style="' + st({ borderTop: '1px solid ' + K.line, padding: '8px 6px 8px' }) + '"><div style="' + st({ padding: '2px 8px 4px', fontSize: '12px', fontWeight: 600, color: K.muted }) + '">' + s[0] + '</div>' + s[1].map((r) => '<div style="' + st({ display: 'flex', alignItems: 'center', gap: '10px', minHeight: r.tall ? '50px' : '38px', padding: '0 8px', borderRadius: '9px', background: r.on ? K.press : 'transparent' }) + '">' + r.h + '</div>').join('') + '</div>').join(''), { overflow: 'hidden' }); };
const bbar = (inner, right, o) => { o = o || {}; return card({ left: '12px', right: (right || 12) + 'px', bottom: '12px' }, inner, Object.assign({ display: 'flex', alignItems: 'center', gap: '2px', padding: '8px', minHeight: '60px' }, o)); };
const spacer = '<span style="flex: 1;"></span>';
const lrow = (d, name, fact) => ic(d, 15, 1.8, K.muted) + t(name, { flex: 1, fontWeight: 500, fontSize: '13.5px' }) + (fact ? mu(fact, { fontSize: '12.5px' }) : '') + ic(I.chev, 14, 1.8, K.faint);
const lanes = (on) => ['A', 'B', 'C', 'D', 'E'].map((x) => ({ h: lrow(I.row, 'Lane ' + x, x === 'E' ? '6 pens' : '50 stalls'), on: x === on }));
const doneGroup = '<span style="display: inline-flex; color: ' + K.ink + '; padding: 0 8px;">' + ic(I.undo, 18) + '</span><span style="display: inline-flex; color: #B5BCB3; padding: 0 8px;">' + ic(I.redo, 18) + '</span>' + btn(I.check, 'Done', { dark: true });
const viewTabs = (on, pigs) => btn(I.cal, 'Schedule', { on: on === 'sched' }) + btn(I.pig, 'Pigs', { n: pigs || '186', on: on === 'pigs' }) + btn(I.tool, 'Devices', { dot: K.red, on: on === 'dev' });
const devIcons = { climate: 'M14 14.8V4a2 2 0 1 0-4 0v10.8a4 4 0 1 0 4 0Z', fan: 'M12 12m-2 0a2 2 0 1 0 4 0 2 2 0 1 0-4 0M12 10c0-4 1-7 4-7 2 0 2 3-1 5M14 12c4 0 7 1 7 4 0 2-3 2-5-1M12 14c0 4-1 7-4 7-2 0-2-3 1-5M10 12c-4 0-7-1-7-4 0-2 3-2 5 1', temp: 'M12 3s6 6.4 6 11a6 6 0 0 1-12 0c0-4.6 6-11 6-11Z', nh3: 'M3 9h11a3 3 0 1 0-3-3M3 15h15a3 3 0 1 1-3 3M3 12h7', feeder: 'M5 10h14l-2 10H7L5 10Zm3-6 1 6m7-6-1 6', water: 'M4 7h16M7 7v4a5 5 0 0 0 10 0V7M12 16v5', heat: 'M9 18h6M10 21h4M12 3a6 6 0 0 0-4 10.5c.7.7 1 1.5 1 2.5h6c0-1 .3-1.8 1-2.5A6 6 0 0 0 12 3Z', floor: 'M3 7h18M3 12h18M3 17h18M16 4l3 3-3 3M8 14l-3 3 3 3', camera: 'M3 7h12v10H3zM15 10l6-3v10l-6-3', scale: 'M12 4v16M5 8h14M5 8l-3 7h6L5 8Zm14 0-3 7h6l-3-7Z' };
const devGroups = [['Climate', [['climate', 'Climate controller', 'Runs fans and heat for the room'], ['fan', 'Ventilation fan', 'Moves air through the room'], ['temp', 'Temperature and humidity', 'Reads where it hangs'], ['nh3', 'Ammonia sensor', 'Reads where it hangs']]], ['Feed and water', [['feeder', 'Feeder', 'Feeds the pens on its line'], ['water', 'Water line', 'Drinkers for the pens on its line']]], ['Comfort', [['heat', 'Heat lamps', 'Warms the pens it hangs over'], ['floor', 'Moving floor', 'Clears the floor under its pens']]], ['Other', [['camera', 'Camera', 'Watches the pens in view'], ['scale', 'Scale', 'Weighs pigs from its pens']]]];

const frames = {
  v1: { cap: 'At rest. Left: where you are. Bottom: 3D, what you can open, and Select, in one bar. The right is empty, kept for the window.', html: () => leftCard('Gestation 2', 'Room · 148 sows, 4 boars', '<span style="color: ' + K.red + '; font-weight: 600;">2 urgent</span> · 3 to watch', [['Inside', [{ h: lrow(I.row, 'Lane A', '50 sows') }, { h: lrow(I.row, 'Lane B', '50 sows') }, { h: lrow(I.row, 'Lane C', '48 sows') }, { h: lrow(I.row, 'Lane D', '4 boars') }]]], { back: true }) + bbar(btn(I.cube, '3D', { caret: true }) + sep + viewTabs('') + spacer + btn(I.select, 'Select')) },
  v2: { cap: 'Schedule opens as the window on the right, full height. The bottom bar ends where the window begins, so they can never meet; the card on the left still says where you are.', html: () => leftCard('Production Zone 1', 'Zone · 3 sections · 1,375 pigs', '', [], { back: true }) + panel(phead('Schedule', 'Production Zone 1 · this week'), sched()) + bbar(btn(I.cube, '3D', { caret: true }) + sep + viewTabs('sched', '1,375') + spacer + btn(I.select, 'Select'), PR) },
  v3: { cap: 'A Schedule row opens its task straight in the window; one camera move to Farrowing Room 4, its pens coloured. The card follows to the room. The back chip, Esc or empty map return the camera and the card to Production Zone 1.', html: () => leftCard('Farrowing Room 4', 'Room · Batch 33 · 26 sows', '', [], { back: true }) + panel(phead('Move into Farrowing Room 4', 'Batch 33 · day 2 of 3', { back: 'Schedule · Production Zone 1' }), sec('Progress', '26 sows') + box([{ h: '<div style="padding: 14px 0;">' + ring(26, 26, K.green, 'All moved in') + '</div>' }]) + sec('Next') + box([{ h: t('Fri 6 Nov', { width: '86px', color: K.muted, fontSize: '13px' }) + t('Farrowing starts, ~6 litters') }, { h: t('Sat 7 Nov', { width: '86px', color: K.muted, fontSize: '13px' }) + t('Farrowing, ~14 litters') }])) + bbar(btn(I.cube, '3D', { caret: true }) + sep + viewTabs('sched', '26') + spacer + btn(I.select, 'Select'), PR) },
  v4: { cap: 'A pig: her record is the window; the card says where she is; the camera puts her pen in the free middle. The bar is the same bar.', html: () => leftCard('Pen C24', 'Gestation 2 · lane C', '', [], { back: true }) + panel(phead('205783', 'Sow · C24 · Gestation 2', { back: 'Gestation 2' }), sec('Now') + box([{ h: t('Gestation', { fontSize: '16px', fontWeight: 600 }) + mu('day 78 of 115') }]) + sec('Details') + '<div style="display: grid; grid-template-columns: 1fr 1fr; gap: 8px;">' + [['Parity', '2'], ['Breed', 'LY'], ['Weight', '192 kg'], ['Backfat', '13 mm'], ['Teats', '14'], ['Feed', '2.6 kg / day']].map((x) => '<div style="padding: 10px 12px; background: #FFFFFF; border: 1px solid ' + K.line + '; border-radius: 12px;"><div style="font-size: 12.5px; color: ' + K.muted + ';">' + x[0] + '</div><div style="font-size: 15px; font-weight: 600;">' + x[1] + '</div></div>').join('') + '</div><div style="display: flex; gap: 8px; margin-top: 16px;">' + fbtn(ic(I.chart, 16) + '&nbsp; Performance') + fbtn(ic(I.log, 16) + '&nbsp; Log') + '</div>') + bbar(btn(I.cube, '3D', { caret: true }) + sep + viewTabs('') + spacer + btn(I.select, 'Select'), PR) },
  e1: { cap: 'Edit, at rest: the same three places. The card holds the room and what is inside it; the bar holds Add, the room\'s actions, and undo · redo · Done at its right end.', html: () => leftCard('Gestation 1', 'Room · Z1-GES-1', '19.1 × 35.3 m · 206 places', [['Inside', lanes('')]], { back: true }) + bbar(btn(I.cube, '3D', { caret: true }) + sep + btn(I.plus, 'Add', { dark: true, caret: true }) + btn(I.corners, 'Reshape walls') + btn(I.copy, 'Duplicate') + btn(I.more, 'More') + spacer + doneGroup) },
  e2: { cap: 'Add › Row: Plan, the room fills the map, and the bar itself becomes the guide. No other step on screen.', html: () => leftCard('Gestation 1', 'Room · Z1-GES-1', '', []) + bbar(btn(I.cube, 'Plan', { caret: true }) + sep + '<span style="' + st({ display: 'inline-flex', alignItems: 'center', justifyContent: 'center', width: '36px', height: '36px', borderRadius: '10px', background: K.ink, color: '#FFFFFF', flex: 'none', margin: '0 6px' }) + '">' + ic(I.row, 18) + '</span><span style="display: flex; flex-direction: column; gap: 1px;">' + t('Place a row', { fontWeight: 600, fontSize: '15px' }) + mu('A green box follows your pointer. Click by the door or at the far end.') + '</span>' + spacer + '<span style="' + st({ display: 'inline-flex', alignItems: 'center', height: '40px', padding: '0 14px', borderRadius: '10px', boxShadow: 'inset 0 0 0 1px #D5DACF', fontWeight: 600 }) + '">Cancel</span>') },
  e3: { cap: 'Add › Device: the bar grows upward into a sheet as wide as the map. The four groups sit side by side, so nothing wraps into chips. Picking one turns the sheet back into the guide.', html: () => leftCard('Gestation 1', 'Room · Z1-GES-1', '19.1 × 35.3 m · 206 places', [['Inside', lanes('')]], { back: true }) + card({ left: '12px', right: '12px', bottom: '12px' }, '<div style="' + st({ display: 'flex', alignItems: 'flex-start', gap: '10px', padding: '14px 16px 6px' }) + '"><span style="display: flex; flex-direction: column; gap: 2px; flex: 1;">' + t('Add a device', { fontSize: '17px', fontWeight: 600 }) + mu('Pick what it is. You place it on the map next.') + '</span><span style="display: inline-flex; color: ' + K.muted + '; padding: 4px;">' + ic(I.x, 18) + '</span></div><div style="' + st({ display: 'grid', gridTemplateColumns: 'repeat(4, 1fr)', gap: '10px', padding: '6px 12px 14px' }) + '">' + devGroups.map((g) => '<div><div style="' + st({ padding: '6px 8px', fontSize: '12px', fontWeight: 600, color: K.muted }) + '">' + g[0] + '</div>' + g[1].map((x) => '<div style="' + st({ display: 'flex', alignItems: 'flex-start', gap: '10px', padding: '9px 8px', borderRadius: '10px' }) + '"><span style="' + st({ display: 'inline-flex', alignItems: 'center', justifyContent: 'center', width: '30px', height: '30px', borderRadius: '9px', background: K.press, flex: 'none' }) + '">' + ic(devIcons[x[0]], 16) + '</span><span style="display: flex; flex-direction: column; gap: 1px; min-width: 0;">' + t(x[1], { fontSize: '13.5px', fontWeight: 500, whiteSpace: 'normal' }) + mu(x[2], { fontSize: '12px', lineHeight: '16px', whiteSpace: 'normal' }) + '</span></div>').join('') + '</div>').join('') + '</div>') },
  e4: { cap: 'A lane picked: the card becomes the lane (its pens from the door, with steppers); the bar becomes the lane\'s actions, Remove apart at the end. ✕ on the card goes back to the room.', html: () => leftCard('Lane C', 'Lane · Z1-GES-2-C · 22 pens', '', [['Pens, from the door', [{ h: sw('#A7CDAE') + '<span style="flex: 1; display: flex; flex-direction: column;">' + t('Gestation stall', { fontWeight: 500, fontSize: '13.5px' }) + mu('C1–C12', { fontSize: '12px' }) + '</span>' + step('12'), tall: true }, { h: sw('#9FD3C8') + '<span style="flex: 1; display: flex; flex-direction: column;">' + t('Group pen', { fontWeight: 500, fontSize: '13.5px' }) + mu('C13–C22', { fontSize: '12px' }) + '</span>' + step('10'), tall: true }]]], { crumb: 'Gestation 2 ' + ic(I.chev, 12), x: true }) + bbar(btn(I.cube, '3D', { caret: true }) + sep + btn(I.plus, 'Add pens', { dark: true }) + btn(I.copy, 'Copy lane') + sep + '<span style="color: ' + K.red + '; display: inline-flex;">' + btn(I.trash, 'Remove lane') + '</span>' + spacer + doneGroup) }
};

